-- Store-scoped workforce, immutable performance/commission facts and payroll approval.
set statement_timeout='30s';set lock_timeout='5s';

alter table public.salon_staff add column base_salary numeric(12,2) not null default 0 check(base_salary>=0);
create table public.salon_commission_rules(id bigint generated always as identity primary key,organization_id bigint not null,store_id bigint,category text not null check(category in('service','product')),name text not null check(nullif(btrim(name),'') is not null),rate numeric(6,3) not null check(rate between 0 and 100),valid_from date not null,valid_to date,status text not null default 'active' check(status in('active','disabled')),created_by_staff_id bigint not null,created_at timestamptz not null default now(),check(valid_to is null or valid_to>=valid_from),unique(organization_id,id),foreign key(organization_id,store_id) references public.salon_stores(organization_id,id),foreign key(organization_id,created_by_staff_id) references public.salon_staff(organization_id,id));
create index salon_commission_rules_scope_idx on public.salon_commission_rules(organization_id,store_id,category,status,valid_from desc);
create table public.salon_performance_ledger(id bigint generated always as identity primary key,organization_id bigint not null,store_id bigint not null,staff_id bigint not null,order_id bigint not null,order_line_id bigint not null,refund_request_id bigint,reversal_of_id bigint,entry_type text not null check(entry_type in('sale','refund')),category text not null check(category in('service','product')),gross_amount numeric(12,2) not null check((entry_type='sale' and gross_amount>=0) or (entry_type='refund' and gross_amount<0)),commission_rate numeric(6,3) not null check(commission_rate between 0 and 100),commission_amount numeric(12,2) not null,occurred_at timestamptz not null,created_at timestamptz not null default now(),unique(organization_id,id),foreign key(organization_id,store_id) references public.salon_stores(organization_id,id),foreign key(organization_id,staff_id) references public.salon_staff(organization_id,id),foreign key(organization_id,order_id) references public.salon_orders(organization_id,id),foreign key(organization_id,order_line_id) references public.salon_order_lines(organization_id,id),foreign key(organization_id,refund_request_id) references public.salon_refund_requests(organization_id,id),foreign key(organization_id,reversal_of_id) references public.salon_performance_ledger(organization_id,id));
create unique index salon_performance_sale_line_idx on public.salon_performance_ledger(organization_id,order_line_id) where entry_type='sale';
create unique index salon_performance_refund_line_idx on public.salon_performance_ledger(organization_id,refund_request_id,order_line_id) where entry_type='refund';
create index salon_performance_staff_date_idx on public.salon_performance_ledger(organization_id,store_id,staff_id,occurred_at);
create table public.salon_payroll_runs(id bigint generated always as identity primary key,organization_id bigint not null,store_id bigint not null,staff_id bigint not null,payroll_month date not null check(extract(day from payroll_month)=1),status text not null default 'draft' check(status in('draft','approved','rejected','paid','cancelled')),base_salary numeric(12,2) not null,gross_performance numeric(12,2) not null,refund_performance numeric(12,2) not null,net_performance numeric(12,2) not null,commission_total numeric(12,2) not null,bonus numeric(12,2) not null default 0 check(bonus>=0),deduction numeric(12,2) not null default 0 check(deduction>=0),payable_total numeric(12,2) not null,adjustment_reason text not null default '',generated_by_staff_id bigint not null,reviewed_by_staff_id bigint,review_reason text not null default '',created_at timestamptz not null default now(),reviewed_at timestamptz,unique(organization_id,id),unique(organization_id,store_id,staff_id,payroll_month),foreign key(organization_id,store_id) references public.salon_stores(organization_id,id),foreign key(organization_id,staff_id) references public.salon_staff(organization_id,id),foreign key(organization_id,generated_by_staff_id) references public.salon_staff(organization_id,id),foreign key(organization_id,reviewed_by_staff_id) references public.salon_staff(organization_id,id));
create index salon_payroll_scope_idx on public.salon_payroll_runs(organization_id,store_id,payroll_month,status);
do $$declare t text;begin foreach t in array array['salon_commission_rules','salon_performance_ledger','salon_payroll_runs'] loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant all on table public.%I to service_role',t);end loop;end$$;

alter table public.salon_operation_requests drop constraint salon_operation_requests_action_check;
alter table public.salon_operation_requests add constraint salon_operation_requests_action_check check(action in ('checkout','refund','inventory_move','customer_create','customer_status','customer_relation','catalog_create','catalog_enable','catalog_status','inventory_count','member_open','member_recharge','member_status','order_create','order_lines','order_status','refund_request','refund_review','refund_execute','finance_entry','staff_create','staff_status','commission_rule','payroll_generate','payroll_review'));

create or replace function salon_private.record_paid_order_performance() returns trigger language plpgsql security invoker set search_path='' as $$declare v_line record;v_rate numeric(6,3);v_date date;v_timezone text;begin select timezone into v_timezone from public.salon_stores where organization_id=new.organization_id and id=new.store_id;v_date:=(new.paid_at at time zone v_timezone)::date;for v_line in select * from public.salon_order_lines where organization_id=new.organization_id and order_id=new.id and staff_id is not null and item_type in('service','product') loop select r.rate into v_rate from public.salon_commission_rules r where r.organization_id=new.organization_id and (r.store_id=new.store_id or r.store_id is null) and r.category=v_line.item_type and r.status='active' and r.valid_from<=v_date and (r.valid_to is null or r.valid_to>=v_date) order by (r.store_id is not null) desc,r.valid_from desc,r.id desc limit 1;v_rate:=coalesce(v_rate,0);insert into public.salon_performance_ledger(organization_id,store_id,staff_id,order_id,order_line_id,entry_type,category,gross_amount,commission_rate,commission_amount,occurred_at) values(new.organization_id,new.store_id,v_line.staff_id,new.id,v_line.id,'sale',v_line.item_type,v_line.line_total,v_rate,round(v_line.line_total*v_rate/100,2),new.paid_at);end loop;return new;end$$;
create trigger salon_orders_paid_performance after update of status on public.salon_orders for each row when(new.status='paid' and old.status is distinct from 'paid') execute function salon_private.record_paid_order_performance();

create or replace function salon_private.record_refund_performance() returns trigger language plpgsql security invoker set search_path='' as $$declare v_line record;v_source public.salon_performance_ledger;begin for v_line in select rl.order_line_id,rl.refund_amount,ol.staff_id,ol.item_type,ol.order_id from public.salon_refund_request_lines rl join public.salon_order_lines ol on ol.organization_id=rl.organization_id and ol.id=rl.order_line_id where rl.organization_id=new.organization_id and rl.refund_request_id=new.id and ol.staff_id is not null and ol.item_type in('service','product') loop select * into v_source from public.salon_performance_ledger p where p.organization_id=new.organization_id and p.order_line_id=v_line.order_line_id and p.entry_type='sale';insert into public.salon_performance_ledger(organization_id,store_id,staff_id,order_id,order_line_id,refund_request_id,reversal_of_id,entry_type,category,gross_amount,commission_rate,commission_amount,occurred_at) values(new.organization_id,new.store_id,v_line.staff_id,v_line.order_id,v_line.order_line_id,new.id,case when found then v_source.id else null end,'refund',v_line.item_type,-v_line.refund_amount,case when found then v_source.commission_rate else 0 end,case when found then -round(v_line.refund_amount*v_source.commission_rate/100,2) else 0 end,new.executed_at);end loop;return new;end$$;
create trigger salon_refunds_executed_performance after update of status on public.salon_refund_requests for each row when(new.status='executed' and old.status is distinct from 'executed') execute function salon_private.record_refund_performance();

create or replace function public.salon_create_staff(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_request_key text,p_staff_no text,p_display_name text,p_role_id bigint,p_position text default '',p_level_name text default '',p_base_salary numeric default 0) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_id bigint;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'staff','write');if nullif(btrim(coalesce(p_staff_no,'')),'') is null or nullif(btrim(coalesce(p_display_name,'')),'') is null or p_base_salary<0 or (p_role_id is not null and not exists(select 1 from public.salon_roles where organization_id=p_organization_id and id=p_role_id and status='active')) then raise exception '员工资料参数无效';end if;v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'staff_create','staff_payload',hashtextextended(jsonb_build_object('no',upper(btrim(p_staff_no)),'name',btrim(p_display_name),'role',p_role_id,'position',btrim(coalesce(p_position,'')),'level',btrim(coalesce(p_level_name,'')),'salary',round(p_base_salary,2))::text,0));if v_op.completed_at is not null then return v_op.response_json;end if;begin insert into public.salon_staff(organization_id,store_id,role_id,staff_no,display_name,position,level_name,base_salary) values(p_organization_id,p_store_id,p_role_id,upper(btrim(p_staff_no)),btrim(p_display_name),btrim(coalesce(p_position,'')),btrim(coalesce(p_level_name,'')),round(p_base_salary,2)) returning id into v_id;exception when unique_violation then raise exception '员工编号已经存在';end;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json) values(p_organization_id,p_store_id,p_actor_staff_id,'staff',v_id::text,'create',jsonb_build_object('staffNo',upper(btrim(p_staff_no)),'displayName',btrim(p_display_name),'position',btrim(coalesce(p_position,''))));v_response:=jsonb_build_object('staffId',v_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_set_staff_status(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_target_staff_id bigint,p_request_key text,p_status text,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_staff public.salon_staff;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'staff','write');if p_status not in('active','leave','departed') or nullif(btrim(coalesce(p_reason,'')),'') is null or (p_target_staff_id=p_actor_staff_id and p_status='departed') then raise exception '员工状态或变更原因无效';end if;v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'staff_status','staff_status_'||p_status,p_target_staff_id);if v_op.completed_at is not null then return v_op.response_json;end if;select * into v_staff from public.salon_staff where organization_id=p_organization_id and store_id=p_store_id and id=p_target_staff_id for update;if not found or v_staff.employment_status=p_status then raise exception '员工不存在或已经是目标状态';end if;update public.salon_staff set employment_status=p_status,effective_to=case when p_status='departed' then current_date else null end where organization_id=p_organization_id and id=p_target_staff_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'staff',p_target_staff_id::text,'status_change',jsonb_build_object('status',v_staff.employment_status),jsonb_build_object('status',p_status),btrim(p_reason));v_response:=jsonb_build_object('staffId',p_target_staff_id,'status',p_status);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_create_commission_rule(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_request_key text,p_category text,p_name text,p_rate numeric,p_valid_from date,p_valid_to date default null) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_id bigint;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'commission','write');if p_category not in('service','product') or nullif(btrim(coalesce(p_name,'')),'') is null or p_rate not between 0 and 100 or p_valid_from is null or (p_valid_to is not null and p_valid_to<p_valid_from) then raise exception '提成规则参数无效';end if;if exists(select 1 from public.salon_commission_rules where organization_id=p_organization_id and store_id=p_store_id and category=p_category and status='active' and daterange(valid_from,coalesce(valid_to,'infinity'::date),'[]') && daterange(p_valid_from,coalesce(p_valid_to,'infinity'::date),'[]')) then raise exception '该类别有效期内已有提成规则';end if;v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'commission_rule','commission_payload',hashtextextended(jsonb_build_object('category',p_category,'name',btrim(p_name),'rate',round(p_rate,3),'from',p_valid_from,'to',p_valid_to)::text,0));if v_op.completed_at is not null then return v_op.response_json;end if;insert into public.salon_commission_rules(organization_id,store_id,category,name,rate,valid_from,valid_to,created_by_staff_id) values(p_organization_id,p_store_id,p_category,btrim(p_name),round(p_rate,3),p_valid_from,p_valid_to,p_actor_staff_id) returning id into v_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json) values(p_organization_id,p_store_id,p_actor_staff_id,'commission_rule',v_id::text,'create',jsonb_build_object('category',p_category,'rate',round(p_rate,3),'validFrom',p_valid_from,'validTo',p_valid_to));v_response:=jsonb_build_object('commissionRuleId',v_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_generate_payroll(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_staff_id bigint,p_request_key text,p_month date,p_bonus numeric default 0,p_deduction numeric default 0,p_reason text default '') returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_staff public.salon_staff;v_timezone text;v_gross numeric(12,2);v_refund numeric(12,2);v_commission numeric(12,2);v_id bigint;v_total numeric(12,2);v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'payroll','generate');if p_month is null or extract(day from p_month)<>1 or coalesce(p_bonus,0)<0 or coalesce(p_deduction,0)<0 or ((coalesce(p_bonus,0)>0 or coalesce(p_deduction,0)>0) and nullif(btrim(coalesce(p_reason,'')),'') is null) then raise exception '工资试算参数无效';end if;v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'payroll_generate','payroll_payload',hashtextextended(jsonb_build_object('staff',p_staff_id,'month',p_month,'bonus',round(coalesce(p_bonus,0),2),'deduction',round(coalesce(p_deduction,0),2),'reason',btrim(coalesce(p_reason,'')))::text,0));if v_op.completed_at is not null then return v_op.response_json;end if;select * into v_staff from public.salon_staff where organization_id=p_organization_id and store_id=p_store_id and id=p_staff_id for update;if not found then raise exception '员工不存在或不属于当前门店';end if;select timezone into v_timezone from public.salon_stores where organization_id=p_organization_id and id=p_store_id;select coalesce(round(sum(gross_amount) filter(where entry_type='sale'),2),0),coalesce(round(-sum(gross_amount) filter(where entry_type='refund'),2),0),coalesce(round(sum(commission_amount),2),0) into v_gross,v_refund,v_commission from public.salon_performance_ledger where organization_id=p_organization_id and store_id=p_store_id and staff_id=p_staff_id and (occurred_at at time zone v_timezone)::date>=p_month and (occurred_at at time zone v_timezone)::date<(p_month+interval '1 month')::date;v_total:=round(v_staff.base_salary+v_commission+coalesce(p_bonus,0)-coalesce(p_deduction,0),2);begin insert into public.salon_payroll_runs(organization_id,store_id,staff_id,payroll_month,base_salary,gross_performance,refund_performance,net_performance,commission_total,bonus,deduction,payable_total,adjustment_reason,generated_by_staff_id) values(p_organization_id,p_store_id,p_staff_id,p_month,v_staff.base_salary,v_gross,v_refund,v_gross-v_refund,v_commission,round(coalesce(p_bonus,0),2),round(coalesce(p_deduction,0),2),v_total,btrim(coalesce(p_reason,'')),p_actor_staff_id) returning id into v_id;exception when unique_violation then raise exception '该员工本月工资已经生成';end;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'payroll',v_id::text,'generate',jsonb_build_object('staffId',p_staff_id,'month',p_month,'commission',v_commission,'payable',v_total),btrim(coalesce(p_reason,'')));v_response:=jsonb_build_object('payrollId',v_id,'status','draft','commissionTotal',v_commission,'payableTotal',v_total);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_review_payroll(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_payroll_id bigint,p_request_key text,p_decision text,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_payroll public.salon_payroll_runs;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'payroll','approve');if p_decision not in('approved','rejected') or nullif(btrim(coalesce(p_reason,'')),'') is null then raise exception '工资审批决定或意见无效';end if;v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'payroll_review','payroll_'||p_decision,p_payroll_id);if v_op.completed_at is not null then return v_op.response_json;end if;select * into v_payroll from public.salon_payroll_runs where organization_id=p_organization_id and store_id=p_store_id and id=p_payroll_id for update;if not found or v_payroll.status<>'draft' then raise exception '工资单不存在或当前不可审批';end if;if v_payroll.generated_by_staff_id=p_actor_staff_id then raise exception '工资单生成与审批不能为同一人';end if;update public.salon_payroll_runs set status=p_decision,reviewed_by_staff_id=p_actor_staff_id,review_reason=btrim(p_reason),reviewed_at=now() where organization_id=p_organization_id and id=p_payroll_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'payroll',p_payroll_id::text,'review',jsonb_build_object('status','draft'),jsonb_build_object('status',p_decision),btrim(p_reason));v_response:=jsonb_build_object('payrollId',p_payroll_id,'status',p_decision);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_list_payroll(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_month date default null) returns setof public.salon_payroll_runs language plpgsql security invoker set search_path='' as $$begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'payroll','read');return query select * from public.salon_payroll_runs p where p.organization_id=p_organization_id and p.store_id=p_store_id and (p_month is null or p.payroll_month=p_month) order by p.payroll_month desc,p.id desc;end$$;

revoke execute on function salon_private.record_paid_order_performance() from public,anon,authenticated;revoke execute on function salon_private.record_refund_performance() from public,anon,authenticated;
revoke execute on function public.salon_create_staff(bigint,bigint,bigint,text,text,text,bigint,text,text,numeric) from public,anon,authenticated;
revoke execute on function public.salon_set_staff_status(bigint,bigint,bigint,bigint,text,text,text) from public,anon,authenticated;
revoke execute on function public.salon_create_commission_rule(bigint,bigint,bigint,text,text,text,numeric,date,date) from public,anon,authenticated;
revoke execute on function public.salon_generate_payroll(bigint,bigint,bigint,bigint,text,date,numeric,numeric,text) from public,anon,authenticated;
revoke execute on function public.salon_review_payroll(bigint,bigint,bigint,bigint,text,text,text) from public,anon,authenticated;
revoke execute on function public.salon_list_payroll(bigint,bigint,bigint,date) from public,anon,authenticated;
grant execute on function public.salon_create_staff(bigint,bigint,bigint,text,text,text,bigint,text,text,numeric) to service_role;
grant execute on function public.salon_set_staff_status(bigint,bigint,bigint,bigint,text,text,text) to service_role;
grant execute on function public.salon_create_commission_rule(bigint,bigint,bigint,text,text,text,numeric,date,date) to service_role;
grant execute on function public.salon_generate_payroll(bigint,bigint,bigint,bigint,text,date,numeric,numeric,text) to service_role;
grant execute on function public.salon_review_payroll(bigint,bigint,bigint,bigint,text,text,text) to service_role;
grant execute on function public.salon_list_payroll(bigint,bigint,bigint,date) to service_role;
